mapper.select:
select id, order_id as orderId, order_number as orderNumber, shop_id as shopId, user_id as userId, user_name as userName, user_avatar as userAvatar, rating, content, images, reply, reply_time as replyTime, create_time as createTime from review
and shop_id = #{shopId}
and rating = #{rating}
order by create_time desc

mapper.update:
update review
set reply = #{reply}, reply_time = #{replyTime}
where id = #{id} and shop_id = #{shopId}

mapper.select:
select avg(rating) as avgRating, count(*) as reviewCount
from review
where shop_id = #{shopId}

select shop_id as shopId, avg(rating) as avgRating, count(*) as reviewCount from review where shop_id in
#{shopId}
group by shop_id
